var DATA = {"pattern": "invoice refund charge payment billing", "destination": "billing-handler", "threshold": "0.4", "fallback": "general-handler", "example": "why was my invoice charged twice"};
function score(q, pattern) {
  var words = pattern.toLowerCase().split(/[^a-z]+/).filter(Boolean);
  var ql = q.toLowerCase(), hits = 0;
  words.forEach(function (w) { if (ql.indexOf(w) >= 0) hits++; });
  return words.length ? hits / words.length : 0;
}
var questions = [DATA.example, "what is the weather today", "help me reset my password now"];
console.log("Route pattern: " + DATA.pattern + " -> " + DATA.destination);
questions.forEach(function (q) {
  var s = score(q, DATA.pattern), th = parseFloat(DATA.threshold);
  var dest = s >= th ? DATA.destination : DATA.fallback;
  console.log("  Q: " + q);
  console.log("    score=" + s.toFixed(2) + " threshold=" + th + " => " + dest);
});
console.log("RESULT: routing demonstrated with confidence threshold " + DATA.threshold + ".");

